export const DialogFallback: FallbackProtocol = {
	async ask(params, protocol) {
		return askViaDialogs(
			protocol,
			params.question,
			params.context,
			params.options,
			params.allowMultiple,
			params.allowFreeform,
			params.allowComment,
			params.timeout,
		);
	},
};

